<script lang="ts">import { dishes, evidence } from '$lib/data'; let query = ''; let region = 'All'; $: shown = dishes.filter(d => (region === 'All' || d.region === region) && [d.italianName,d.englishDescription,...(d.aliases || [])].join(' ').toLowerCase().includes(query.toLowerCase()));</script>
<section class="pageintro"><p class="eyebrow">THE MENU TRANSLATOR</p><h1>Italian food dictionary</h1><p>Learn the actual Italian names before you order. Every dish links to restaurants with sourced menu evidence.</p></section>
<div class="controls"><label>Search Italian or English<input bind:value={query} placeholder="e.g. cinghiale, wild boar, cecina"/></label><label>Region<select bind:value={region}><option>All</option>{#each [...new Set(dishes.map(d => d.region))].sort() as r}<option>{r}</option>{/each}</select></label></div>
<div class="cards">{#each shown as dish (dish.id)}<a class="card linkcard" href="/foods/{dish.id}"><span class="tag">{dish.region}</span><h2>{dish.italianName}</h2><p>{dish.englishDescription}</p><p class="muted">{new Set(evidence.filter(e => e.foodId === dish.id && e.evidenceStatus !== 'unverified').map(e => e.placeId)).size} sourced places →</p></a>{/each}</div>
